s=s.replace("        local=raw._expert_lookup[ids+1]\n", "")
s=s.replace("        # Both graphs replay on freshly changed activations, route IDs and scores.", "        eager_diff=a.float()-b.float()\n        eager_rel=(eager_diff.norm()/b.float().norm().clamp_min(1e-20)).item()\n        eager_abs=eager_diff.abs().max().item()\n        assert torch.isfinite(a).all() and eager_rel<=.003 and eager_abs<=.03125,(m,pattern,'eager',eager_rel,eager_abs)\n        del eager_diff\n        replay_rows=[]\n        # Every graph also transitions to all-remote routes, then back to its pattern.")
s=s.replace("            ids.copy_(torch.tensor(make_routes(m,8,args.experts*8,8,pattern,replay_seed)", "            replay_pattern='all_remote' if replay_seed==239 else pattern\n            ids.copy_(torch.tensor(make_routes(m,8,args.experts*8,8,replay_pattern,replay_seed)")
s=s.replace("            assert torch.isfinite(oa).all() and rr<=.003 and aa<=.03125,(m,pattern,replay_seed,rr,aa)", "            valid=bool(torch.isfinite(oa).all()) and rr<=.003 and aa<=.03125\n            if replay_pattern=='all_remote':valid=valid and bool((oa==0).all()) and bool((ob==0).all())\n            replay_rows.append({'seed':replay_seed,'routing':replay_pattern,'relative_l2':rr,'max_abs':aa,'passed':valid})\n            if not valid:\n                report['failure']={'m':m,'pattern':pattern,'replays':replay_rows}\n                (args.out/'results.json').write_text(json.dumps(report,indent=2))\n                raise AssertionError((m,pattern,replay_seed,rr,aa))")
s=s.replace("row={'m':m,'pattern':pattern,", "row={'m':m,'pattern':pattern,'eager_relative_l2':eager_rel,'eager_max_abs':eager_abs,'replays':replay_rows,")
s=s.replace("        if (args.out/'STOP_AFTER_CASE').exists():", "        del gb,ga,ob,oa,b,a,dd,diff\n        torch.cuda.synchronize()\n        if (args.out/'STOP_AFTER_CASE').exists():")
