f=p/'memory_probe.py';s=f.read_text(encoding='utf-8-sig')
s=s.replace("from kernel_runtime import bootstrap", "from probe_preflight import preflight\nprovenance=preflight(a.sglang_root)\nif not a.tokens or any(m<=0 for m in a.tokens):raise ValueError('Provide positive token sizes')\nfrom kernel_runtime import bootstrap")
s=s.replace("tree=ast.parse(export.read_text())", "tree=ast.parse(export.read_text(encoding='utf-8'))")
s=s.replace("prepare_peak=torch.cuda.max_memory_allocated();gc.collect()", "torch.cuda.synchronize();prepare_peak=torch.cuda.max_memory_allocated();prepare_reserved_peak=torch.cuda.max_memory_reserved();gc.collect()")
s=s.replace("'runtime':runtime,", "'runtime':runtime,'provenance':provenance,")
s=s.replace("'prepare_peak_allocated':prepare_peak,", "'prepare_peak_allocated':prepare_peak,'prepare_peak_reserved':prepare_reserved_peak,")
s=s.replace("'peak_allocated':torch.cuda.max_memory_allocated()", "'peak_allocated':torch.cuda.max_memory_allocated(),'peak_reserved':torch.cuda.max_memory_reserved()")
s=s.replace(" # Cooperative handoff:", " # Replay changing live buffers after recording allocation metrics. Arithmetic\n # comparison is performed by frozen_helper_probe, not this memory-only probe.\n x.neg_();ids.fill_(e);scores.fill_(1.0/8)\n graph.replay();torch.cuda.synchronize();assert bool((output==0).all())\n ids.zero_();graph.replay();torch.cuda.synchronize();assert bool(torch.isfinite(output).all())\n # Cooperative handoff:")
